import {
    Acl,
    Role,
    default_view,
    ApplicationMenu,
    Property,
    UserPreference,
    CrossScopePrivilege,
    List,
    Record,
    BusinessRule,
    ClientScript,
} from '@servicenow/sdk/core'

const role_meta = Role({
    $meta: {
        installMethod: 'demo',
    },
    name: 'x_meta.role_meta',
})

Acl({
    $id: Now.ID['acl-id-meta'],
    $meta: {
        installMethod: 'demo',
    },
    operation: 'write',
    type: 'record',
    table: 'task',
    roles: [role_meta],
    condition: 'priority=2^active=true',
    field: 'description',
    appliesTo: 'active=true',
})

List({
    $meta: {
        installMethod: 'demo',
    },
    table: 'sys_atf_test',
    view: default_view,
    columns: ['name'],
})

const appCategoryMeta = Record({
    $meta: {
        installMethod: 'demo',
    },
    table: 'sys_app_category',
    $id: Now.ID[`sys_app_category_my_app_meta`],
    data: {
        name: 'My App Category Meta',
        style: 'border: 1px solid #96bcdc; background-color: #FBFBFB;',
        default_order: 100,
    },
})

ApplicationMenu({
    $meta: {
        installMethod: 'demo',
    },
    $id: Now.ID['My App Menu Meta'],
    title: 'My App Menu',
    hint: 'This is a hint',
    description: 'This is a description',
    category: appCategoryMeta,
    roles: [role_meta],
    active: true,
})

UserPreference({
    $meta: {
        installMethod: 'demo',
    },
    name: 'email',
    $id: Now.ID['admin_email_meta'],
    type: 'string',
    value: 'admin@example.com',
})

CrossScopePrivilege({
    $meta: {
        installMethod: 'demo',
    },
    $id: Now.ID['cross_meta'],
    targetName: 'Script Type',
    targetScope: 'sn_example',
    status: 'allowed',
    targetType: 'scriptable',
    operation: 'execute',
})

BusinessRule({
    $meta: {
        installMethod: 'demo',
    },
    name: 'ts',
    table: 'blah',
    $id: '2',
    script: ``,
    when: 'after',
})

ClientScript({
    $meta: {
        installMethod: 'demo',
    },
    $id: Now.ID['cs_meta'],
    type: 'onLoad',
    table: 'incident',
    script: `function onLoad(){ console.log("execute this code") }`,
    name: 'handle_incidents',
    description: 'cool',
    uiType: 'all',
})

Property({
    $meta: {
        installMethod: 'demo',
    },
    $id: Now.ID['newPropMeta'],
    name: 'x_meta.some.new.prop_meta',
    type: 'string',
    value: 'hello',
    description: 'Brand new prop',
    roles: {
        read: ['admin'],
    },
})
